style.css:
@-moz-document domain("youtube.com") {
/* Tech Blueprint Variables */
  :root {
    --cyber-bg: #020205 !important;
    --cyber-panel: #070913 !important;
    --cyber-glow: #00ffcc !important;
    --cyber-alert: #ff0055 !important;
    --cyber-text: #a5c2f3 !important;
    --cyber-grid: rgba(0, 255, 204, 0.07) !important;
  }

  /* Core Tech-Grid Background */
  body, html, ytd-app, #content, #page-manager {
    background-color: var(--cyber-bg) !important;
    background-image: 
      linear-gradient(var(--cyber-grid) 1px, transparent 1px),
      linear-gradient(90deg, var(--cyber-grid) 1px, transparent 1px) !important;
    background-size: 40px 40px !important;
    color: var(--cyber-text) !important;
  }

  /* Floating UI Command Panels */
  #masthead-container, #guide-content, ytd-playlist-panel-renderer {
    background: var(--cyber-panel) !important;
    border-bottom: 2px solid var(--cyber-glow) !important;
    box-shadow: 0 4px 20px rgba(0, 255, 204, 0.1) !important;
  }

  #guide-content {
    border-right: 2px solid var(--cyber-glow) !important;
    border-bottom: none !important;
  }

  /* Holographic Search Bar */
  #container.ytd-searchbox {
    background-color: #000000 !important;
    border: 1px solid var(--cyber-glow) !important;
    border-radius: 0px !important; /* Sharp corners */
    box-shadow: inset 0 0 8px var(--cyber-glow) !important;
  }

  #search-icon-legacy.ytd-searchbox {
    background-color: var(--cyber-panel) !important;
    border: 1px solid var(--cyber-glow) !important;
    border-left: none !important;
    color: var(--cyber-glow) !important;
  }

  /* Neon Text Overrides */
  #video-title, .title.ytd-video-primary-info-renderer, h1, h2, h3 {
    color: #ffffff !important;
    text-shadow: 0 0 5px rgba(0, 255, 204, 0.5) !important;
  }

  /* Action Buttons & Interactions */
  yt-icon, .style-scope.ytd-toggle-button-renderer {
    color: var(--cyber-glow) !important;
  }

  /* Laser Progress Bar */
  .ytp-play-progress, #progress.yt-page-navigation-progress {
    background: var(--cyber-alert) !important;
    box-shadow: 0 0 15px var(--cyber-alert), 0 0 5px #ffffff !important;
  }

  /* Sharp Tech Video Cards */
  ytd-rich-grid-media, ytd-compact-video-renderer {
    border: 1px solid rgba(165, 194, 243, 0.1) !important;
    padding: 10px !important;
    background: rgba(7, 9, 19, 0.6) !important;
    backdrop-filter: blur(4px) !important;
    transition: all 0.2s ease-in-out !important;
  }

  ytd-rich-grid-media:hover {
    border-color: var(--cyber-glow) !important;
    box-shadow: 0 0 12px rgba(0, 255, 204, 0.2) !important;
    transform: translateY(-2px) !important;
  }
}
